def the_readback(case, data):
    """THE TABLE — THE READBACK (THE LOOP's step 6 — the forms on file, no new form): the table's census; the supplied rows (14:1, 14:3, 14:22, 14:28 WITH THEIR WRITES; 14:5, 14:11, 14:20, 14:25 the chapter's own gains) and 14:21 EXPANDED with its write; no pointer row; no retrograde row (no act told only here — measured); the twin diffed on the DB; the verses no one cites"""
    del P_[:]
    ask = case['ask']
    if ask == 'the_table':
        ink('14:1-29', 'twenty-nine verses, twenty-nine rows — one per verse; THE CHAPTER IS LAW FROM ITS FIRST WORD TO ITS LAST — no imperative, no first person, no narrative verb, the one "and when" at 14:24; the register plural for the food laws, singular for the tithe, 14:21 both %s' % (([v for v, (p, s) in NUM.items() if p and not s], [v for v, (p, s) in NUM.items() if s and not p], [v for v, (p, s) in NUM.items() if p and s]),))
        move('THE LOOP.md step 6 — the readback\'s forms T1-T6 on file', "chapter 14 takes the forms already on file: T4 the laws' form — every row graded against the cell that compiles its kin, by CALL (%d rows — every row has kin, 11b's lesson 8); T1 reference rows against the tape's lines by kind and first verse (%d rows); EIGHT rows SUPPLIED — four AS LAWS WITH THEIR WRITES (the code's holes compiled at the chapter's own day), 14:5 the ten named, 14:11 and 14:20 the permission Leviticus lacks, 14:25 the money's first seat; 14:21 EXPANDED with its write; no pointer, no state row, no stretch, no retrograde row — the grades %s" % (sum(1 for r in READBACK if r['cell']), sum(1 for r in READBACK if r['tape_kind']), dict(sorted(RB_GRADES.items()))))
        dat('every reference row\'s entry FOUND (the tape lines by kind and first verse; every kin cell answering) — asserted on the module; no hole, no open row, no stretch, no retrograde row, no state row')
        return out("the table — twenty-nine rows, one per verse: the grades %s; %d on the tape by kind and first verse, %d in the kin's cells by CALL, %d SUPPLIED (four with their writes) and 14:21 EXPANDED with its write; no pointer row, no hole, no open row, no stretch, no state row, no retrograde row" % (dict(sorted(RB_GRADES.items())), sum(1 for r in READBACK if r['tape_kind']), sum(1 for r in READBACK if r['cell']), sum(1 for r in READBACK if r['grade'] == 'SUPPLIED')), ['accepted'])
    if ask == 'the_supplied_rows':
        ink('14:1, 14:3, 14:22, 14:28', 'the four law rows SUPPLIED WITH THEIR WRITES — cuttings_for_the_dead_barred, abomination_eating_barred, second_tithe_owed, poor_tithe_owed; 14:21 EXPANDED with carcass_eating_barred (the writes %s); 14:5, 14:11, 14:20, 14:25 SUPPLIED as the chapter\'s own gains' % ([r['write'] for r in READBACK if r['write']],))
